R"VICTUSMSL(#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct Sky
{
    float4x4 inv_view_proj;
    float4 zenith;
    float4 horizon;
    float4 ground;
    float4 sun_dir;
    float4 sun_color;
};

struct main0_out
{
    float4 out_color [[color(0)]];
};

struct main0_in
{
    float2 v_uv [[user(locn0)]];
};

fragment main0_out main0(main0_in in [[stage_in]], constant Sky& sky [[buffer(0)]])
{
    main0_out out = {};
    float2 ndc = float2((in.v_uv.x * 2.0) - 1.0, 1.0 - (in.v_uv.y * 2.0));
    float4 far_p = sky.inv_view_proj * float4(ndc, 1.0, 1.0);
    float4 near_p = sky.inv_view_proj * float4(ndc, 0.0, 1.0);
    float3 dir = fast::normalize((far_p.xyz / float3(far_p.w)) - (near_p.xyz / float3(near_p.w)));
    float h = dir.y;
    float3 _79;
    if (h > 0.0)
    {
        _79 = mix(sky.horizon.xyz, sky.zenith.xyz, float3(powr(h, 0.5)));
    }
    else
    {
        _79 = mix(sky.horizon.xyz, sky.ground.xyz, float3(powr(-h, 0.4000000059604644775390625)));
    }
    float3 c = _79;
    float s = dot(dir, fast::normalize(sky.sun_dir.xyz));
    c += ((sky.sun_color.xyz * smoothstep(sky.sun_color.w, 1.0, s)) + ((sky.sun_color.xyz * 0.07999999821186065673828125) * powr(fast::max(s, 0.0), 64.0)));
    out.out_color = float4(c, 1.0);
    return out;
}

)VICTUSMSL";
